                                max_cursor, int(event.get("cursor", 0))
                            )
            self._history_cursor = max_cursor
        # DID 密钥吊销历史游标：按租户各自维护的持久化正整数
        # （tenant_id -> cursor），同一租户内不同 DID 的吊销事件共享
        # 该游标空间。旧状态文件无该字段时，从各租户已有吊销历史项的
        # 最大 cursor 推导。
